import argparse
import re
import sys
from datetime import datetime, timezone
from urllib.parse import quote, urljoin

import pandas as pd
from playwright.sync_api import sync_playwright, TimeoutError as PlaywrightTimeoutError


OUTPUT_COLUMNS = [
    'Product Title', 'Model Code', 'Price (INR)', 'Color options',
    'Storage capacity', 'Display specs', 'Camera specs',
    'Availability status', 'Source URL'
]
FLAG_COLUMNS = ['Timestamp', 'URL', 'Flag type', 'Message']


def log(message):
    print(f'[{datetime.now().astimezone().isoformat(timespec="seconds")}] {message}', flush=True)


def get_proxy():
    return None


def solve_captcha(*args, **kwargs):
    raise NotImplementedError('CAPTCHA solving and anti-bot bypass are not implemented')


def detect_anti_bot_signals(response, body=''):
    signals = []
    status = getattr(response, 'status', response if isinstance(response, int) else None)
    url = getattr(response, 'url', '') if not isinstance(response, int) else ''
    text = body or ''
    lowered = text.lower()
    if status in (403, 429):
        signals.append(f'HTTP status {status}')
    markers = {
        'captcha': 'CAPTCHA marker',
        'cloudflare': 'Cloudflare marker',
        'perimeterx': 'PerimeterX marker',
        'datadome': 'DataDome marker',
        'javascript is disabled': 'JavaScript-disabled response marker',
        'enable javascript': 'JavaScript-required response marker'
    }
    for marker, description in markers.items():
        if marker in lowered:
            signals.append(description)
    if text and len(text.strip()) < 500:
        signals.append(f'Unusually short response body ({len(text.strip())} characters)')
    return signals


def add_flag(flags, url, flag_type, message):
    flags.append({
        'Timestamp': datetime.now(timezone.utc).isoformat(),
        'URL': url or '',
        'Flag type': flag_type,
        'Message': message
    })


def dismiss_cookie_banner(page, flags, url):
    attempted = True
    matches = ['Accept all', 'Accept', 'I agree', 'Allow all', 'Agree']
    try:
        for text in matches:
            locator = page.get_by_role('button', name=re.compile(rf'^\\s*{re.escape(text)}\\s*$', re.I)).first
            if locator.count() and locator.is_visible(timeout=400):
                locator.click(timeout=700)
                log(f'Cookie consent dismissed on {url}')
                return True
    except Exception:
        pass
    if attempted:
        log(f'Cookie dismissal was attempted but no matching button was found on {url}')
        add_flag(flags, url, 'possible layout change', 'Cookie dismissal attempted but no common consent button matched')
    return False


def safe_goto(page, url, flags):
    log(f'Opening {url}')
    try:
        page.goto(url, wait_until='domcontentloaded', timeout=30000)
        # This must remain the first operation after every successful page.goto.
        dismiss_cookie_banner(page, flags, url)
        return True
    except Exception as exc:
        add_flag(flags, url, 'error', f'Navigation failed: {exc}')
        return False


def first_text(page, selectors):
    for selector in selectors:
        try:
            locator = page.locator(selector).first
            if locator.count() and locator.is_visible(timeout=500):
                value = locator.inner_text(timeout=1000).strip()
                if value:
                    return value
        except Exception:
            continue
    return ''


def page_text(page):
    try:
        return page.locator('body').inner_text(timeout=3000)
    except Exception:
        return ''


def labeled_value(text, labels):
    label_pattern = '|'.join(re.escape(label) for label in labels)
    match = re.search(rf'(?:{label_pattern})\\s*[:\\-]?\\s*([^\\n|;]+)', text, re.I)
    return match.group(1).strip() if match else ''


def extract_detail(page, url, flags):
    text = page_text(page)
    title = first_text(page, [
        '#productTitle', 'h1 span', 'h1', '[data-feature-name="title"]'
    ])
    if not title:
        title = first_text(page, ['title'])
    price = first_text(page, [
        '.a-price .a-offscreen', '#priceblock_ourprice', '#priceblock_dealprice',
        '.a-price-whole'
    ])
    if price and not re.search(r'(?:₹|INR)', price, re.I):
        price = ''
    model = labeled_value(text, ['model number', 'model code', 'item model number', 'model'])
    if not model:
        match = re.search(r'\\b[A-Z0-9][A-Z0-9._-]{2,}\\b', text)
        model = match.group(0) if match else ''
    color = labeled_value(text, ['color', 'colour'])
    storage = labeled_value(text, ['storage', '容量', 'memory storage', 'hard disk size'])
    display = labeled_value(text, ['display', 'screen size', 'display size', 'resolution'])
    camera = labeled_value(text, ['camera', 'rear camera', 'front camera'])
    availability = first_text(page, [
        '#availability', '#outOfStock', '#buybox', '.a-color-success', '.a-color-price'
    ])
    if not availability:
        availability = labeled_value(text, ['availability', 'in stock', 'currently unavailable'])
    if not availability:
        availability = 'Unknown'

    low_confidence = []
    if not title:
        low_confidence.append('product title was not found')
    for field, value in [('Model Code', model), ('Price (INR)', price), ('Color options', color),
                         ('Storage capacity', storage), ('Display specs', display),
                         ('Camera specs', camera)]:
        if not value:
            low_confidence.append(f'{field} was not found')
    if low_confidence:
        add_flag(flags, url, 'low-confidence extraction', '; '.join(low_confidence))
    if not text or 'javascript is disabled' in text.lower():
        add_flag(flags, url, 'blocked or empty page', 'No usable rendered product content was available')

    return {
        'Product Title': title,
        'Model Code': model,
        'Price (INR)': price,
        'Color options': color,
        'Storage capacity': storage,
        'Display specs': display,
        'Camera specs': camera,
        'Availability status': availability,
        'Source URL': url
    }


def product_links(page, base_url, keyword=''):
    links = []
    keyword_lower = keyword.lower().strip()
    try:
        anchors = page.locator('a[href*="/dp/"], a[href*="/gp/product/"]')
        for index in range(anchors.count()):
            anchor = anchors.nth(index)
            href = anchor.get_attribute('href') or ''
            label = anchor.inner_text(timeout=500).strip()
            absolute = urljoin(base_url, href)
            haystack = f'{label} {absolute}'.lower()
            if keyword_lower and keyword_lower not in haystack:
                continue
            if absolute not in links:
                links.append(absolute)
    except Exception:
        pass
    return links


def excluded_product(title, url):
    haystack = f'{title} {url}'.lower()
    return any(term in haystack for term in ['accessor', 'case', 'refurbished', 'renewed'])


def main():
    parser = argparse.ArgumentParser(description='Amazon product scraper')
    parser.add_argument('--input', default='input.xlsx')
    parser.add_argument('--output', default='output.xlsx')
    parser.add_argument('--max-products', type=int, default=None)
    args = parser.parse_args()

    log(f'Reading input workbook {args.input}')
    try:
        input_df = pd.read_excel(args.input)
    except Exception as exc:
        log(f'Could not read input workbook: {exc}')
        raise

    results = []
    flags = []
    processed = 0

    with sync_playwright() as playwright:
        log('Starting Chromium browser; Amazon was observed to require JavaScript rendering')
        browser = playwright.chromium.launch(headless=True, proxy=get_proxy())
        context = browser.new_context()

        def inspect_response(response):
            try:
                body = response.body().decode('utf-8', errors='ignore')
            except Exception:
                body = ''
            for signal in detect_anti_bot_signals(response, body):
                add_flag(flags, response.url, 'anti-bot signal', signal)

        context.on('response', inspect_response)
        page = context.new_page()

        for row_number, row in input_df.iterrows():
            if args.max_products is not None and processed >= args.max_products:
                break
            keyword = str(row.get('keyword', '') or '').strip()
            listing_url = str(row.get('listing_url', '') or '').strip()
            detail_url = str(row.get('detail_url', '') or '').strip()

            if detail_url:
                # Independent fast path: it does not depend on a listing crawl.
                if safe_goto(page, detail_url, flags):
                    item = extract_detail(page, detail_url, flags)
                    if not excluded_product(item['Product Title'], detail_url):
                        results.append(item)
                        processed += 1
                    else:
                        add_flag(flags, detail_url, 'filtered product', 'Ignored accessory, case, refurbished, or renewed item')
                continue

            target_listing = listing_url
            if not target_listing and keyword:
                target_listing = f'https://www.amazon.com/s?k={quote(keyword)}'
            if not target_listing:
                add_flag(flags, '', 'error', f'Input row {row_number + 2} has no keyword, listing_url, or detail_url')
                continue

            if not safe_goto(page, target_listing, flags):
                continue
            links = product_links(page, target_listing, keyword)
            if not links:
                add_flag(flags, target_listing, 'low-confidence extraction', 'No product links were observed; the page may be JavaScript-disabled or structurally changed')
            for link in links:
                if args.max_products is not None and processed >= args.max_products:
                    break
                if not safe_goto(page, link, flags):
                    continue
                item = extract_detail(page, link, flags)
                title_or_slug = f'{item["Product Title"]} {link}'.lower()
                if keyword and keyword.lower() not in title_or_slug:
                    add_flag(flags, link, 'filtered product', 'Title or URL does not contain the requested keyword')
                    continue
                if excluded_product(item['Product Title'], link):
                    add_flag(flags, link, 'filtered product', 'Ignored accessory, case, refurbished, or renewed item')
                    continue
                results.append(item)
                processed += 1

        context.close()
        browser.close()

    log(f'Writing {len(results)} extracted items and {len(flags)} flags to {args.output}')
    extracted_df = pd.DataFrame(results, columns=OUTPUT_COLUMNS)
    flags_df = pd.DataFrame(flags, columns=FLAG_COLUMNS)
    with pd.ExcelWriter(args.output, engine='openpyxl') as writer:
        extracted_df.to_excel(writer, sheet_name='Extracted Data', index=False)
        flags_df.to_excel(writer, sheet_name='Flags', index=False)
    log('Run complete')


if __name__ == '__main__':
    main()

import argparse
import re
import sys
from datetime import datetime, timezone
from urllib.parse import quote_plus, urljoin

import pandas as pd
from playwright.sync_api import sync_playwright, TimeoutError as PlaywrightTimeoutError


TARGET = "https://www.amazon.com/"


def log(message):
    timestamp = datetime.now(timezone.utc).isoformat(timespec="seconds")
    print(f"[{timestamp}] {message}", flush=True)


def get_proxy():
    """Proxy configuration is intentionally not implemented."""
    return None


def solve_captcha(*args, **kwargs):
    """CAPTCHA solving and anti-bot bypass are intentionally not implemented."""
    raise NotImplementedError("CAPTCHA solving is not implemented")


def detect_anti_bot_signals(response, body=None):
    """Return anti-bot signal descriptions for one HTTP response."""
    signals = []
    status = getattr(response, "status", None)
    url = getattr(response, "url", "")
    if status in (403, 429):
        signals.append(f"HTTP status {status}")

    headers = getattr(response, "headers", {}) or {}
    content_type = str(headers.get("content-type", "")).lower()
    text = (body or "")[:200000].lower()
    markers = {
        "captcha": "CAPTCHA marker",
        "cloudflare": "Cloudflare marker",
        "perimeterx": "PerimeterX marker",
        "datadome": "DataDome marker",
    }
    for marker, description in markers.items():
        if marker in text:
            signals.append(description)

    if body is not None and ("text/html" in content_type or not content_type):
        if len(body.strip()) < 200:
            signals.append("Unusually short HTML response body")
    return signals


def dismiss_cookie_banner(page, flags, page_url):
    """Try common consent controls; absence is recorded as a possible layout change."""
    consent_texts = ["Accept all", "Accept", "I agree", "Allow all", "Agree"]
    matched = False
    attempted = True
    try:
        for text in consent_texts:
            locator = page.get_by_role("button", name=re.compile(rf"^{re.escape(text)}$", re.I)).first
            if locator.count() and locator.is_visible(timeout=700):
                locator.click(timeout=700)
                matched = True
                log(f"Dismissed a consent control on {page_url}")
                break
    except Exception:
        pass
    if attempted and not matched:
        log(f"No consent control matched on {page_url}; possible layout change")
        flags.append({
            "Type": "low-confidence extraction",
            "URL": page_url,
            "Message": "No common cookie-consent button matched; possible layout change",
        })


def navigate(page, url, flags):
    """Navigate and immediately perform the required consent check."""
    log(f"Navigating to {url}")
    try:
        response = page.goto(url, wait_until="domcontentloaded", timeout=30000)
        # This must remain immediately after every page.goto call.
        dismiss_cookie_banner(page, flags, url)
        if response is not None:
            try:
                body = response.text()
            except Exception:
                body = None
            for signal in detect_anti_bot_signals(response, body):
                flags.append({"Type": "anti-bot signal", "URL": url, "Message": signal})
        return True
    except PlaywrightTimeoutError as exc:
        flags.append({"Type": "error", "URL": url, "Message": f"Navigation timeout: {exc}"})
        return False
    except Exception as exc:
        flags.append({"Type": "error", "URL": url, "Message": f"Navigation failed: {exc}"})
        return False


def first_text(page, selectors):
    for selector in selectors:
        try:
            locator = page.locator(selector).first
            if locator.count() and locator.is_visible(timeout=500):
                value = locator.inner_text(timeout=1000).strip()
                if value:
                    return value
        except Exception:
            continue
    return ""


def clean_text(value):
    return re.sub(r"\s+", " ", value or "").strip()


def extract_detail(page, detail_url, listing_url, keyword, flags):
    current_url = page.url or detail_url
    title = first_text(page, ["#productTitle", "h1"])
    asin = ""
    try:
        asin = page.locator("#detailBullets_feature_div li, #prodDetails tr").all_inner_texts()
        asin = " ".join(asin)
    except Exception:
        asin = ""
    asin_match = re.search(r"\bB0[A-Z0-9]{8}\b|\b[0-9A-Z]{10}\b", asin, re.I)
    asin = asin_match.group(0) if asin_match else ""
    if not asin:
        asin_match = re.search(r"/(?:dp|gp/product)/([A-Z0-9]{10})", current_url, re.I)
        asin = asin_match.group(1) if asin_match else ""

    category = first_text(page, ["#wayfinding-breadcrumbs_feature_div", "nav[aria-label='Breadcrumb']"])
    cost = first_text(page, ["#corePriceDisplay_desktop_feature_div .a-price", "#priceblock_ourprice", "#priceblock_dealprice", ".a-price.aok-align-center"])
    msrp = first_text(page, [".basisPrice", "#priceblock_listprice", "span.a-text-price"])
    ratings = first_text(page, ["#acrPopover", "#averageCustomerReviews .a-icon-alt"])
    reviews = first_text(page, ["#acrCustomerReviewLink", "#averageCustomerReviews"])
    badge = first_text(page, ["#dealBadge_feature_div", "#acBadge_feature_div", ".badge-wrapper"])

    if not title:
        flags.append({"Type": "low-confidence extraction", "URL": current_url, "Message": "Product title selector returned no value"})
    if not asin:
        flags.append({"Type": "low-confidence extraction", "URL": current_url, "Message": "ASIN could not be identified"})

    return {
        "Category": clean_text(category),
        "Retailers": "Amazon",
        "List Page URL": listing_url,
        "Product Title": clean_text(title),
        "asin": asin,
        "Product Cost": clean_text(cost),
        "MSRP": clean_text(msrp),
        "Ratings": clean_text(ratings),
        "Reviews": clean_text(reviews),
        "Item Badge": clean_text(badge),
        "Product URL": current_url,
    }


def collect_listing_links(page, listing_url, keyword, flags):
    links = []
    cards = page.locator("[data-component-type='s-search-result']")
    try:
        count = cards.count()
    except Exception:
        count = 0
    for index in range(count):
        card = cards.nth(index)
        try:
            title = first_text(card, ["h2", "h2 a"])
            anchor = card.locator("h2 a, a.a-link-normal").first
            href = anchor.get_attribute("href") if anchor.count() else None
            if not href:
                continue
            absolute = urljoin(listing_url, href)
            haystack = f"{title} {absolute}".lower()
            if keyword and keyword.lower() not in haystack:
                continue
            links.append(absolute.split("?")[0])
        except Exception:
            continue

    if not links:
        flags.append({"Type": "low-confidence extraction", "URL": listing_url, "Message": "No verified Amazon listing selectors or product links were found"})
    return list(dict.fromkeys(links))


def handle_row(row, page, results, flags, max_products, processed):
    keyword = clean_text(str(row.get("keyword", "")) if pd.notna(row.get("keyword", "")) else "")
    listing_url = clean_text(str(row.get("listing_url", "")) if pd.notna(row.get("listing_url", "")) else "")
    detail_url = clean_text(str(row.get("detail_url", "")) if pd.notna(row.get("detail_url", "")) else "")

    # Independent detail_url fast path: it never depends on a listing crawl.
    if detail_url:
        if navigate(page, detail_url, flags):
            results.append(extract_detail(page, detail_url, listing_url, keyword, flags))
            processed[0] += 1
        return

    if not listing_url:
        if keyword:
            listing_url = f"{TARGET}s?k={quote_plus(keyword)}"
        else:
            flags.append({"Type": "error", "URL": "", "Message": "Row has neither detail_url, listing_url, nor keyword"})
            return

    if not navigate(page, listing_url, flags):
        return
    links = collect_listing_links(page, listing_url, keyword, flags)
    for product_url in links:
        if max_products is not None and processed[0] >= max_products:
            break
        if navigate(page, product_url, flags):
            results.append(extract_detail(page, product_url, listing_url, keyword, flags))
            processed[0] += 1


def main():
    parser = argparse.ArgumentParser(description="Amazon scraper")
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    args = parser.parse_args()

    log(f"Reading input workbook {args.input}")
    try:
        input_df = pd.read_excel(args.input)
    except Exception as exc:
        log(f"Could not read input workbook: {exc}")
        raise

    results = []
    flags = []
    processed = [0]
    with sync_playwright() as playwright:
        log("Launching Chromium browser for JavaScript-rendered pages")
        browser = playwright.chromium.launch(headless=True, proxy=get_proxy())
        context = browser.new_context(user_agent="Mozilla/5.0 (compatible; ScraperStudio/1.0)")
        page = context.new_page()

        def response_handler(response):
            try:
                content_type = str(response.headers.get("content-type", "")).lower()
                body = response.text() if ("text/html" in content_type or not content_type) else None
                for signal in detect_anti_bot_signals(response, body):
                    flags.append({"Type": "anti-bot signal", "URL": response.url, "Message": signal})
            except Exception:
                pass

        page.on("response", response_handler)
        for _, row in input_df.iterrows():
            if args.max_products is not None and processed[0] >= args.max_products:
                break
            handle_row(row, page, results, flags, args.max_products, processed)
        browser.close()

    log(f"Writing {len(results)} extracted items and {len(flags)} flags to {args.output}")
    columns = ["Category", "Retailers", "List Page URL", "Product Title", "asin", "Product Cost", "MSRP", "Ratings", "Reviews", "Item Badge", "Product URL"]
    flags_columns = ["Type", "URL", "Message"]
    with pd.ExcelWriter(args.output, engine="openpyxl") as writer:
        pd.DataFrame(results, columns=columns).to_excel(writer, sheet_name="Extracted Data", index=False)
        pd.DataFrame(flags, columns=flags_columns).to_excel(writer, sheet_name="Flags", index=False)
    log("Run complete")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        log(f"Fatal error: {exc}")
        sys.exit(1)

import argparse
import re
from datetime import datetime, timezone
from urllib.parse import urljoin

import pandas as pd
import requests
from bs4 import BeautifulSoup

BASE_URL = "https://books.toscrape.com/"
USER_AGENT = "Mozilla/5.0 (compatible; ScraperStudio/1.0)"
RATING_VALUES = {"one": 1, "two": 2, "three": 3, "four": 4, "five": 5}


def log(message):
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    print(f"[{timestamp}] {message}", flush=True)


def get_proxy():
    return None


def solve_captcha(*args, **kwargs):
    raise NotImplementedError("CAPTCHA solving is intentionally not implemented")


def detect_anti_bot_signals(response):
    """Return signals found in an HTTP response; this never bypasses anti-bot controls."""
    signals = []
    body = response.text or ""
    lowered = body.lower()
    url = response.url

    if response.status_code == 403:
        signals.append("HTTP 403 Forbidden")
    if response.status_code == 429:
        signals.append("HTTP 429 Too Many Requests")

    markers = {
        "captcha": "CAPTCHA marker",
        "cloudflare": "Cloudflare marker",
        "perimeterx": "PerimeterX marker",
        "datadome": "DataDome marker",
    }
    for marker, description in markers.items():
        if marker in lowered:
            signals.append(description)

    if len(body.strip()) < 200:
        signals.append("Unusually short response body")

    return [{"signal": signal, "url": url} for signal in signals]


def add_flag(flags, kind, message, url="", context=""):
    flags.append({
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "type": kind,
        "message": message,
        "url": url,
        "context": context,
    })


def fetch(session, url, flags):
    log(f"Fetching {url}")
    try:
        response = session.get(url, timeout=30, allow_redirects=True)
        for signal in detect_anti_bot_signals(response):
            add_flag(flags, "anti-bot", signal["signal"], signal["url"])
        response.raise_for_status()
        return response
    except requests.RequestException as exc:
        add_flag(flags, "error", f"HTTP request failed: {exc}", url)
        log(f"Request failed: {url}: {exc}")
        return None


def clean_text(node):
    return " ".join(node.get_text(" ", strip=True).split()) if node else ""


def rating_from_node(node):
    if not node:
        return None
    classes = node.get("class", [])
    for value in classes:
        normalized = value.strip().lower()
        if normalized in RATING_VALUES:
            return normalized.title()
        if normalized.endswith("-star"):
            name = normalized[:-5]
            if name in RATING_VALUES:
                return name.title()
    text = clean_text(node).lower()
    for name in RATING_VALUES:
        if name in text:
            return name.title()
    return None


def rating_number(rating):
    return RATING_VALUES.get((rating or "").lower())


def parse_price(node):
    value = clean_text(node)
    return value


def parse_availability(node):
    return clean_text(node)


def category_from_detail(soup, fallback=""):
    breadcrumb = soup.select_one("ul.breadcrumb")
    if breadcrumb:
        links = breadcrumb.select("a")
        if len(links) >= 2:
            return clean_text(links[-1])
    return fallback


def extract_detail(response, flags, fallback_category=""):
    soup = BeautifulSoup(response.text, "html.parser")
    title = clean_text(soup.select_one("div.product_main h1, h1"))
    price = parse_price(soup.select_one("div.product_main p.price_color, p.price_color"))
    availability = parse_availability(soup.select_one("div.product_main p.instock, p.instock"))
    rating_node = soup.select_one("div.product_main p.star-rating, p.star-rating")
    rating = rating_from_node(rating_node)
    category = category_from_detail(soup, fallback_category)
    product_url = response.url
    upc = ""

    for row in soup.select("table.table tr"):
        cells = row.find_all(["th", "td"])
        if len(cells) >= 2 and clean_text(cells[0]).lower() == "upc":
            upc = clean_text(cells[1])
            break

    missing = []
    for field, value in (("title", title), ("price", price), ("availability", availability),
                         ("star rating", rating), ("UPC", upc)):
        if not value:
            missing.append(field)
    if missing:
        add_flag(flags, "low-confidence", "Missing detail fields: " + ", ".join(missing), product_url)

    if not rating or rating_number(rating) < 3:
        return None
    if not availability:
        return None
    if "out of stock" in availability.lower():
        return None

    return {
        "Book Title": title,
        "Category": category,
        "Price (GBP)": price,
        "Star Rating": rating,
        "Availability Status": availability,
        "Product URL": product_url,
        "UPC Code": upc,
    }


def listing_cards(soup):
    cards = soup.select("article.product_pod")
    if not cards:
        cards = soup.select("article")
    return cards


def parse_listing(response, fallback_category=""):
    soup = BeautifulSoup(response.text, "html.parser")
    heading = clean_text(soup.select_one("div.page-header h1, h1")) or fallback_category
    items = []
    for card in listing_cards(soup):
        link = card.select_one("h3 a")
        if not link or not link.get("href"):
            continue
        items.append({
            "url": urljoin(response.url, link["href"]),
            "category": heading,
            "listing_title": link.get("title") or clean_text(link),
        })
    next_link = soup.select_one("li.next a")
    next_url = urljoin(response.url, next_link["href"]) if next_link and next_link.get("href") else None
    return items, next_url


def resolve_keyword(session, keyword, flags):
    if keyword.strip().lower() == "travel":
        return urljoin(BASE_URL, "catalogue/category/books/travel_2/index.html"), "Travel"

    response = fetch(session, BASE_URL, flags)
    if not response:
        return None, keyword
    soup = BeautifulSoup(response.text, "html.parser")
    wanted = keyword.strip().casefold()
    for link in soup.select("ul.nav-list a, a"):
        if clean_text(link).casefold() == wanted and link.get("href"):
            return urljoin(response.url, link["href"]), clean_text(link)
    add_flag(flags, "low-confidence", f"No category link matched keyword '{keyword}'", BASE_URL)
    return None, keyword


def crawl_listing(session, start_url, fallback_category, flags, max_products, results, seen_details):
    current = start_url
    seen_pages = set()
    while current and current not in seen_pages:
        if max_products is not None and len(results) >= max_products:
            break
        seen_pages.add(current)
        response = fetch(session, current, flags)
        if not response:
            break
        cards, next_url = parse_listing(response, fallback_category)
        log(f"Found {len(cards)} cards on listing page")
        for card in cards:
            if max_products is not None and len(results) >= max_products:
                break
            detail_url = card["url"]
            if detail_url in seen_details:
                continue
            seen_details.add(detail_url)
            detail_response = fetch(session, detail_url, flags)
            if not detail_response:
                continue
            item = extract_detail(detail_response, flags, card["category"])
            if item:
                results.append(item)
        current = next_url
        if current:
            log("Following next listing page")


def read_cell(row, name):
    value = row.get(name, "")
    if pd.isna(value):
        return ""
    return str(value).strip()


def main():
    parser = argparse.ArgumentParser(description="Books to Scrape category/detail scraper")
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    args = parser.parse_args()

    log("Reading input workbook")
    try:
        input_df = pd.read_excel(args.input)
    except Exception as exc:
        raise SystemExit(f"Could not read input workbook: {exc}")

    results = []
    flags = []
    seen_details = set()
    session = requests.Session()
    session.headers.update({"User-Agent": USER_AGENT, "Accept": "text/html,application/xhtml+xml"})

    for row_number, row in input_df.iterrows():
        if args.max_products is not None and len(results) >= args.max_products:
            break
        keyword = read_cell(row, "keyword")
        listing_url = read_cell(row, "listing_url")
        detail_url = read_cell(row, "detail_url")
        log(f"Processing input row {row_number + 2}")

        if detail_url:
            # Independent fast path: no listing discovery is performed.
            if detail_url in seen_details:
                continue
            seen_details.add(detail_url)
            response = fetch(session, detail_url, flags)
            if response:
                item = extract_detail(response, flags, keyword)
                if item:
                    results.append(item)
        elif listing_url:
            crawl_listing(session, listing_url, keyword, flags, args.max_products, results, seen_details)
        elif keyword:
            resolved, category = resolve_keyword(session, keyword, flags)
            if resolved:
                crawl_listing(session, resolved, category, flags, args.max_products, results, seen_details)
        else:
            add_flag(flags, "error", "Input row has no keyword, listing_url, or detail_url", context=f"row {row_number + 2}")

    columns = ["Book Title", "Category", "Price (GBP)", "Star Rating", "Availability Status", "Product URL", "UPC Code"]
    extracted_df = pd.DataFrame(results, columns=columns)
    flags_columns = ["timestamp", "type", "message", "url", "context"]
    flags_df = pd.DataFrame(flags, columns=flags_columns)
    log(f"Writing {len(extracted_df)} extracted items and {len(flags_df)} flags")
    with pd.ExcelWriter(args.output, engine="openpyxl") as writer:
        extracted_df.to_excel(writer, sheet_name="Extracted Data", index=False)
        flags_df.to_excel(writer, sheet_name="Flags", index=False)
    log("Finished")


if __name__ == "__main__":
    main()

import argparse
import json
import re
import sys
from datetime import datetime, timezone
from urllib.parse import urljoin, urlparse

import pandas as pd
import requests
from bs4 import BeautifulSoup

BASE_URL = "https://restaurants.subway.com/united-states/al"
FIELDS = [
    "Store Number", "Street Address", "City", "State", "Postal Code",
    "Phone Number", "Operating Hours", "Drive-Thru Available", "Delivery Available"
]


def log(message):
    print(f"[{datetime.now().astimezone().isoformat(timespec='seconds')}] {message}", flush=True)


def get_proxy():
    return None


def solve_captcha(*args, **kwargs):
    raise NotImplementedError("CAPTCHA solving is intentionally not implemented")


def detect_anti_bot_signals(response):
    body = response.text or ""
    lower = body.lower()
    markers = {
        "captcha": "captcha",
        "cloudflare": "cloudflare",
        "perimeterx": "perimeterx",
        "datadome": "datadome",
    }
    signals = []
    if response.status_code in (403, 429):
        signals.append(f"HTTP status {response.status_code}")
    for label, marker in markers.items():
        if marker in lower:
            signals.append(f"{label} marker detected")
    if len(body.strip()) < 500:
        signals.append(f"unusually short response body ({len(body.strip())} characters)")
    return signals


def make_session():
    session = requests.Session()
    session.headers.update({
        "User-Agent": "Mozilla/5.0 (compatible; ScraperStudio/1.0)",
        "Accept-Language": "en-US,en;q=0.9",
    })
    proxy = get_proxy()
    if proxy:
        session.proxies.update({"http": proxy, "https": proxy})
    return session


def fetch(session, url, flags):
    log(f"Fetching {url}")
    try:
        response = session.get(url, timeout=30)
        for signal in detect_anti_bot_signals(response):
            flags.append({"Type": "anti-bot", "URL": url, "Message": signal})
        response.raise_for_status()
        return response
    except requests.RequestException as exc:
        flags.append({"Type": "error", "URL": url, "Message": str(exc)})
        log(f"Request failed: {exc}")
        return None


def clean_text(value):
    return re.sub(r"\\s+", " ", value or "").strip()


def page_text(soup):
    return clean_text(soup.get_text(" ", strip=True))


def is_alabama_path(url):
    path = urlparse(url).path.rstrip("/").lower()
    return path.startswith("/united-states/al/")


def city_links(soup, keyword):
    result = []
    wanted = clean_text(keyword).casefold()
    for anchor in soup.find_all("a", href=True):
        href = urljoin(BASE_URL + "/", anchor["href"])
        text = clean_text(anchor.get_text(" ", strip=True))
        parts = [p for p in urlparse(href).path.split("/") if p]
        if is_alabama_path(href) and len(parts) == 3 and wanted in text.casefold():
            if href not in result:
                result.append(href)
    return result


def location_links(soup, listing_url):
    result = []
    listing_parts = [p for p in urlparse(listing_url).path.split("/") if p]
    for anchor in soup.find_all("a", href=True):
        href = urljoin(listing_url, anchor["href"])
        parts = [p for p in urlparse(href).path.split("/") if p]
        if (is_alabama_path(href) and len(parts) > len(listing_parts)
                and href.rstrip("/") != listing_url.rstrip("/")
                and href not in result):
            result.append(href)
    return result


def json_ld_objects(soup):
    objects = []
    for tag in soup.find_all("script", type="application/ld+json"):
        try:
            value = json.loads(tag.string or tag.get_text())
            objects.extend(value if isinstance(value, list) else [value])
        except (ValueError, TypeError):
            continue
    return objects


def first_json_value(objects, keys):
    for obj in objects:
        if not isinstance(obj, dict):
            continue
        for key in keys:
            value = obj.get(key)
            if value and not isinstance(value, (dict, list)):
                return clean_text(str(value))
    return ""


def extract_detail(soup, url):
    text = page_text(soup)
    objects = json_ld_objects(soup)
    address_obj = {}
    for obj in objects:
        if isinstance(obj, dict) and isinstance(obj.get("address"), dict):
            address_obj = obj["address"]
            break
    postal = clean_text(str(address_obj.get("postalCode", "")))
    if not postal:
        match = re.search(r"\\b(\\d{5}(?:-\\d{4})?)\\b", text)
        postal = match.group(1) if match else ""
    phone = first_json_value(objects, ["telephone", "phone"])
    if not phone:
        match = re.search(r"(?:\\+?1[ .-]?)?\\(?\\d{3}\\)?[ .-]\\d{3}[ .-]\\d{4}", text)
        phone = match.group(0) if match else ""

    street = clean_text(str(address_obj.get("streetAddress", "")))
    city = clean_text(str(address_obj.get("addressLocality", "")))
    state = clean_text(str(address_obj.get("addressRegion", ""))) or "AL"
    if not city or not street:
        path_parts = [p for p in urlparse(url).path.split("/") if p]
        if len(path_parts) >= 3 and not city:
            city = path_parts[2].replace("-", " ").title()
        if postal:
            before_postal = text[:text.find(postal)] if postal in text else text
            candidates = [clean_text(x) for x in re.split(r"[|\\n]", before_postal) if clean_text(x)]
            if not street:
                for candidate in reversed(candidates[-8:]):
                    if re.search(r"\\d+\\s+\\S+", candidate):
                        street = candidate
                        break

    hours = []
    for line in soup.get_text("\\n", strip=True).splitlines():
        line = clean_text(line)
        if re.search(r"(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)", line, re.I) and re.search(r"\\d{1,2}:\\d{2}", line):
            if line not in hours:
                hours.append(line)
    if not hours:
        for match in re.findall(r"((?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)[^.;]{0,100}\\d{1,2}:\\d{2}[^.;]{0,40})", text, re.I):
            if match not in hours:
                hours.append(clean_text(match))
    lower = text.casefold()
    drive = "Yes" if re.search(r"drive[- ]?thru|drive[- ]?through", lower) and not re.search(r"no drive[- ]?thru|drive[- ]?thru unavailable", lower) else "No" if re.search(r"no drive[- ]?thru|drive[- ]?thru unavailable", lower) else ""
    delivery = "Yes" if re.search(r"delivery available|offers delivery|delivery", lower) and not re.search(r"no delivery|delivery unavailable", lower) else "No" if re.search(r"no delivery|delivery unavailable", lower) else ""
    store_number = first_json_value(objects, ["storeNumber", "store_number", "branchCode"])
    return {
        "Store Number": store_number,
        "Street Address": street,
        "City": city,
        "State": state,
        "Postal Code": postal,
        "Phone Number": phone,
        "Operating Hours": " ; ".join(hours),
        "Drive-Thru Available": drive,
        "Delivery Available": delivery,
    }


def should_skip(soup):
    text = page_text(soup).casefold()
    closed = re.search(r"\\b(permanently closed|temporarily closed|closed location|closed)\\b", text)
    kiosk = re.search(r"\\b(temporary kiosk|temporary location|kiosk)\\b", text)
    return closed or kiosk, ("closed" if closed else "temporary kiosk" if kiosk else "")


def add_low_confidence_flags(item, url, flags):
    missing = [key for key, value in item.items() if not value]
    if missing:
        flags.append({"Type": "low-confidence", "URL": url, "Message": "Unverified or missing fields: " + ", ".join(missing)})


def process_detail(session, url, rows, flags):
    response = fetch(session, url, flags)
    if not response:
        return
    soup = BeautifulSoup(response.text, "html.parser")
    skip, reason = should_skip(soup)
    if skip:
        log(f"Ignoring {reason} location: {url}")
        return
    item = extract_detail(soup, url)
    rows.append(item)
    add_low_confidence_flags(item, url, flags)


def process_listing(session, url, rows, flags, max_products):
    response = fetch(session, url, flags)
    if not response:
        return
    soup = BeautifulSoup(response.text, "html.parser")
    links = location_links(soup, url)
    if not links:
        flags.append({"Type": "low-confidence", "URL": url, "Message": "No stable individual-location links were found; listing selectors were not verified."})
    for detail in links:
        if max_products is not None and len(rows) >= max_products:
            break
        process_detail(session, detail, rows, flags)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    args = parser.parse_args()
    rows, flags = [], []
    log(f"Reading input workbook {args.input}")
    try:
        input_df = pd.read_excel(args.input)
    except Exception as exc:
        flags.append({"Type": "error", "URL": "", "Message": f"Could not read input workbook: {exc}"})
        input_df = pd.DataFrame()
    session = make_session()
    for _, record in input_df.iterrows():
        if args.max_products is not None and len(rows) >= args.max_products:
            break
        detail = clean_text(str(record.get("detail_url", ""))) if pd.notna(record.get("detail_url", "")) else ""
        listing = clean_text(str(record.get("listing_url", ""))) if pd.notna(record.get("listing_url", "")) else ""
        keyword = clean_text(str(record.get("keyword", ""))) if pd.notna(record.get("keyword", "")) else ""
        if detail:
            log("Using independent detail_url fast path")
            process_detail(session, detail, rows, flags)
        elif listing:
            process_listing(session, listing, rows, flags, args.max_products)
        elif keyword:
            log(f"Matching Alabama city links for keyword {keyword!r}")
            response = fetch(session, BASE_URL, flags)
            if response:
                links = city_links(BeautifulSoup(response.text, "html.parser"), keyword)
                if not links:
                    flags.append({"Type": "low-confidence", "URL": BASE_URL, "Message": f"No city link matched keyword {keyword!r}"})
                for link in links:
                    if args.max_products is not None and len(rows) >= args.max_products:
                        break
                    process_listing(session, link, rows, flags, args.max_products)
        else:
            flags.append({"Type": "error", "URL": "", "Message": "Input row has no keyword, listing_url, or detail_url"})
    if args.max_products is not None:
        rows = rows[:args.max_products]
    log(f"Writing {len(rows)} extracted rows and {len(flags)} flags to {args.output}")
    with pd.ExcelWriter(args.output, engine="openpyxl") as writer:
        pd.DataFrame(rows, columns=FIELDS).to_excel(writer, sheet_name="Extracted Data", index=False)
        pd.DataFrame(flags, columns=["Type", "URL", "Message"]).to_excel(writer, sheet_name="Flags", index=False)
    log("Finished")


if __name__ == "__main__":
    main()

import argparse
import re
from datetime import datetime
from urllib.parse import urljoin, urlparse

import pandas as pd
import requests
from bs4 import BeautifulSoup

BASE_URL = "https://restaurants.subway.com"
STATE_URL = "https://restaurants.subway.com/united-states/al"

DATA_COLUMNS = [
    "Store Number",
    "Street Address",
    "City",
    "State",
    "Postal Code",
    "Phone Number",
    "Operating Hours",
    "Drive-Thru Available",
    "Delivery Available",
    "Source URL",
]
FLAG_COLUMNS = ["timestamp", "flag_type", "message", "url", "keyword"]


def log(message):
    print(f"[{datetime.now().isoformat(timespec='seconds')}] {message}", flush=True)


def get_proxy():
    return None


def solve_captcha(*args, **kwargs):
    raise NotImplementedError("CAPTCHA solving is intentionally not implemented")


def detect_anti_bot_signals(response):
    """Return signals only; this function never attempts to bypass protection."""
    signals = []
    body = response.text or ""
    lower = body.lower()
    if response.status_code in (403, 429):
        signals.append(f"HTTP status {response.status_code}")
    markers = {
        "captcha": "CAPTCHA marker",
        "cloudflare": "Cloudflare marker",
        "perimeterx": "PerimeterX marker",
        "datadome": "DataDome marker",
    }
    for marker, description in markers.items():
        if marker in lower:
            signals.append(description)
    if len(body.strip()) < 500:
        signals.append(f"unusually short response body ({len(body.strip())} characters)")
    return signals


def clean_text(value):
    return re.sub(r"\\s+", " ", value or "").strip()


def make_session():
    session = requests.Session()
    session.headers.update({
        "User-Agent": "Mozilla/5.0 (compatible; ScraperStudio/1.0)",
        "Accept-Language": "en-US,en;q=0.9",
    })
    proxy = get_proxy()
    if proxy:
        session.proxies.update({"http": proxy, "https": proxy})
    return session


def fetch(session, url, flags, keyword=""):
    log(f"Fetching {url}")
    try:
        response = session.get(url, timeout=30)
        for signal in detect_anti_bot_signals(response):
            flags.append({
                "timestamp": datetime.now().isoformat(timespec="seconds"),
                "flag_type": "anti-bot",
                "message": signal,
                "url": url,
                "keyword": keyword,
            })
        response.raise_for_status()
        return response
    except Exception as exc:
        flags.append({
            "timestamp": datetime.now().isoformat(timespec="seconds"),
            "flag_type": "error",
            "message": f"Request failed: {exc}",
            "url": url,
            "keyword": keyword,
        })
        log(f"Request failed for {url}: {exc}")
        return None


def soup_links(html, base_url):
    soup = BeautifulSoup(html, "html.parser")
    links = []
    for anchor in soup.find_all("a", href=True):
        href = urljoin(base_url, anchor.get("href"))
        parsed = urlparse(href)
        if parsed.netloc and parsed.netloc != urlparse(BASE_URL).netloc:
            continue
        links.append((clean_text(anchor.get_text(" ", strip=True)), href.split("#", 1)[0]))
    return soup, links


def path_parts(url):
    return [part for part in urlparse(url).path.split("/") if part]


def city_links(html, page_url, keyword):
    _, links = soup_links(html, page_url)
    wanted = (keyword or "").casefold()
    result = []
    seen = set()
    for text, href in links:
        parts = path_parts(href)
        if len(parts) == 3 and parts[:2] == ["united-states", "al"]:
            candidate = f"{text} {parts[2]}".casefold()
            if wanted in candidate and href not in seen:
                seen.add(href)
                result.append(href)
    return result


def detail_links(html, page_url):
    _, links = soup_links(html, page_url)
    result = []
    seen = set()
    for _, href in links:
        parts = path_parts(href)
        if (len(parts) >= 4 and parts[:2] == ["united-states", "al"]
                and href.rstrip("/") != page_url.rstrip("/") and href not in seen):
            seen.add(href)
            result.append(href)
    return result


def parse_hours(text):
    patterns = [
        r"(?:Mon(?:day)?|Tue(?:sday)?|Wed(?:nesday)?|Thu(?:rsday)?|Fri(?:day)?|Sat(?:urday)?|Sun(?:day)?)[^.;|]{0,80}?\d{1,2}:\d{2}\s*[AP]M[^.;|]{0,20}(?:\d{1,2}:\d{2}\s*[AP]M|Closed)",
    ]
    found = []
    for pattern in patterns:
        found.extend(re.findall(pattern, text, flags=re.I))
    unique = []
    for item in found:
        item = clean_text(item)
        if item not in unique:
            unique.append(item)
    return "; ".join(unique)


def extract_detail(html, url, flags, keyword):
    soup = BeautifulSoup(html, "html.parser")
    text = clean_text(soup.get_text(" ", strip=True))
    lower = text.casefold()
    if "temporary kiosk" in lower or "temporarily closed" in lower or re.search(r"\bclosed\b", lower):
        flags.append({
            "timestamp": datetime.now().isoformat(timespec="seconds"),
            "flag_type": "filtered",
            "message": "Location appears closed or temporary; excluded per rules",
            "url": url,
            "keyword": keyword,
        })
        return None

    row = {column: "" for column in DATA_COLUMNS}
    row["Source URL"] = url
    number_match = re.search(r"(?:store\s*(?:number|no\\.?|#)|location\s*(?:number|no\\.?|#))\s*[:#]?\s*([A-Z0-9-]+)", text, re.I)
    if number_match:
        row["Store Number"] = number_match.group(1)

    address_match = re.search(r"(\d+\s+[^,;|]+?),\s*([A-Za-z .'-]+?),\s*(AL)\s+(\d{5}(?:-\d{4})?)", text, re.I)
    if not address_match:
        address_match = re.search(r"(\d+\s+[^;|]+?)\s+([A-Za-z .'-]+),\s*(AL)\s+(\d{5}(?:-\d{4})?)", text, re.I)
    if address_match:
        row["Street Address"] = clean_text(address_match.group(1))
        row["City"] = clean_text(address_match.group(2))
        row["State"] = address_match.group(3).upper()
        row["Postal Code"] = address_match.group(4)

    phone_match = re.search(r"(?:phone|tel(?:ephone)?)?\s*[:.]?\s*(\(?\d{3}\)?[-. ]\d{3}[-. ]\d{4})", text, re.I)
    if phone_match:
        row["Phone Number"] = phone_match.group(1)
    row["Operating Hours"] = parse_hours(text)

    drive_match = re.search(r"drive[- ]?thru[^.]{0,40}", text, re.I)
    delivery_match = re.search(r"delivery[^.]{0,40}", text, re.I)
    if drive_match:
        row["Drive-Thru Available"] = drive_match.group(0)
    if delivery_match:
        row["Delivery Available"] = delivery_match.group(0)

    uncertain = [name for name in DATA_COLUMNS[:-1] if not row[name]]
    if uncertain:
        flags.append({
            "timestamp": datetime.now().isoformat(timespec="seconds"),
            "flag_type": "low-confidence",
            "message": "Fields not confidently found: " + ", ".join(uncertain),
            "url": url,
            "keyword": keyword,
        })
    return row


def scrape_detail(session, url, flags, keyword):
    response = fetch(session, url, flags, keyword)
    if response is None:
        return None
    return extract_detail(response.text, url, flags, keyword)


def crawl_listing(session, listing_url, flags, keyword, max_products, rows):
    response = fetch(session, listing_url, flags, keyword)
    if response is None:
        return
    links = detail_links(response.text, listing_url)
    if not links:
        flags.append({
            "timestamp": datetime.now().isoformat(timespec="seconds"),
            "flag_type": "low-confidence",
            "message": "No individual location links found; exact DOM selectors were not available in inspection",
            "url": listing_url,
            "keyword": keyword,
        })
    for url in links:
        if max_products is not None and len(rows) >= max_products:
            return
        item = scrape_detail(session, url, flags, keyword)
        if item:
            rows.append(item)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    args = parser.parse_args()

    log("Reading input workbook")
    input_df = pd.read_excel(args.input)
    session = make_session()
    rows, flags = [], []

    for _, record in input_df.iterrows():
        if args.max_products is not None and len(rows) >= args.max_products:
            break
        keyword = "" if pd.isna(record.get("keyword", "")) else str(record.get("keyword", "")).strip()
        detail_url = "" if pd.isna(record.get("detail_url", "")) else str(record.get("detail_url", "")).strip()
        listing_url = "" if pd.isna(record.get("listing_url", "")) else str(record.get("listing_url", "")).strip()

        if detail_url:
            log(f"Using independent detail fast path: {detail_url}")
            item = scrape_detail(session, detail_url, flags, keyword)
            if item:
                rows.append(item)
            continue

        if listing_url:
            log(f"Crawling supplied listing URL: {listing_url}")
            crawl_listing(session, listing_url, flags, keyword, args.max_products, rows)
            continue

        if keyword:
            log(f"Matching city links for keyword: {keyword}")
            response = fetch(session, STATE_URL, flags, keyword)
            if response is not None:
                cities = city_links(response.text, STATE_URL, keyword)
                if not cities:
                    flags.append({
                        "timestamp": datetime.now().isoformat(timespec="seconds"),
                        "flag_type": "low-confidence",
                        "message": "No matching Alabama city link found; search behavior was not observable in inspection",
                        "url": STATE_URL,
                        "keyword": keyword,
                    })
                for city_url in cities:
                    if args.max_products is not None and len(rows) >= args.max_products:
                        break
                    crawl_listing(session, city_url, flags, keyword, args.max_products, rows)

    log("Writing output workbook")
    output_df = pd.DataFrame(rows, columns=DATA_COLUMNS)
    flags_df = pd.DataFrame(flags, columns=FLAG_COLUMNS)
    with pd.ExcelWriter(args.output, engine="openpyxl") as writer:
        output_df.to_excel(writer, sheet_name="Extracted Data", index=False)
        flags_df.to_excel(writer, sheet_name="Flags", index=False)
    log(f"Finished: {len(rows)} extracted item(s), {len(flags)} flag(s)")


if __name__ == "__main__":
    main()

import argparse
import json
import re
import sys
import traceback
from datetime import datetime
from urllib.parse import urljoin, urlparse

from bs4 import BeautifulSoup
from openpyxl import Workbook, load_workbook
from playwright.sync_api import sync_playwright, TimeoutError as PlaywrightTimeoutError

TARGET_URL = "https://www.samsung.com/in/smartphones/all-smartphones/"


def log(message):
    print(f"[{datetime.now().isoformat(timespec='seconds')}] {message}", flush=True)


def get_proxy():
    return None


def solve_captcha(*args, **kwargs):
    raise NotImplementedError("CAPTCHA solving and anti-bot bypass are not implemented")


def detect_anti_bot_signals(status, body, url=""):
    """Return signals only; this function never attempts to bypass anything."""
    signals = []
    text = (body or "")[:100000].lower()
    if status in (403, 429):
        signals.append(f"HTTP status {status}")
    markers = {
        "captcha": "CAPTCHA marker",
        "cloudflare": "Cloudflare marker",
        "cf-chl-": "Cloudflare challenge marker",
        "perimeterx": "PerimeterX marker",
        "datadome": "DataDome marker",
    }
    for marker, description in markers.items():
        if marker in text:
            signals.append(description)
    if len(body or "") < 200:
        signals.append("Unusually short HTTP response body")
    return signals


def dismiss_cookie_banner(page):
    """Try common consent labels; absence of a banner is not fatal."""
    labels = ["Accept all", "Accept", "I agree", "Allow all", "Agree"]
    for label in labels:
        try:
            locator = page.get_by_role("button", name=re.compile(rf"^{re.escape(label)}$", re.I)).first
            if locator.is_visible(timeout=500):
                locator.click(timeout=700)
                log(f"Cookie consent button clicked: {label}")
                return True
        except Exception:
            pass
    log("Cookie dismissal was attempted but no consent button matched; possible layout change")
    return False


def add_flag(flags, flag_type, url, message):
    flags.append({"Type": flag_type, "URL": url or "", "Message": message})


def jsonld_objects(html):
    soup = BeautifulSoup(html, "html.parser")
    objects = []
    for script in soup.select('script[type="application/ld+json"]'):
        try:
            value = json.loads(script.string or script.get_text())
            if isinstance(value, list):
                objects.extend(value)
            else:
                objects.append(value)
        except Exception:
            continue
    return objects


def walk(value):
    yield value
    if isinstance(value, dict):
        for child in value.values():
            yield from walk(child)
    elif isinstance(value, list):
        for child in value:
            yield from walk(child)


def first_key(objects, keys):
    wanted = {key.lower() for key in keys}
    for root in objects:
        for value in walk(root):
            if isinstance(value, dict):
                for key, item in value.items():
                    if key.lower() in wanted and item not in (None, "", []):
                        return item
    return None


def all_key_values(objects, keys):
    wanted = {key.lower() for key in keys}
    result = []
    for root in objects:
        for value in walk(root):
            if isinstance(value, dict):
                for key, item in value.items():
                    if key.lower() in wanted and item not in (None, "", []):
                        if isinstance(item, list):
                            result.extend(item)
                        else:
                            result.append(item)
    return result


def clean_values(values):
    output = []
    for value in values:
        if isinstance(value, dict):
            value = value.get("name") or value.get("value") or value.get("option")
        if value is not None:
            value = str(value).strip()
            if value and value not in output:
                output.append(value)
    return output


def product_items(objects):
    items = []
    for root in objects:
        for value in walk(root):
            if isinstance(value, dict) and str(value.get("@type", "")).lower() == "itemlist":
                entries = value.get("itemListElement", [])
                if isinstance(entries, list):
                    for entry in entries:
                        item = entry.get("item") if isinstance(entry, dict) else entry
                        if isinstance(item, str):
                            items.append({"url": item})
                        elif isinstance(item, dict):
                            items.append(item)
    return items


def title_slug_match(item, keyword):
    if not keyword:
        return True
    needle = str(keyword).strip().lower()
    title = str(item.get("name") or item.get("title") or "").lower()
    slug = urlparse(str(item.get("url") or item.get("@id") or "")).path.lower()
    return needle in title or needle in slug


def extract_detail(page, url, keyword=None):
    html = page.content()
    soup = BeautifulSoup(html, "html.parser")
    objects = jsonld_objects(html)
    title = first_key(objects, ["name", "headline"])
    if not title:
        heading = soup.select_one("h1") or soup.select_one("h2")
        title = heading.get_text(" ", strip=True) if heading else None
    title = str(title).strip() if title else None
    if keyword and not (str(keyword).lower() in (title or "").lower() or str(keyword).lower() in urlparse(url).path.lower()):
        return None

    price = first_key(objects, ["price"])
    if isinstance(price, dict):
        price = price.get("value") or price.get("amount")
    currency = first_key(objects, ["priceCurrency", "currency"])
    model = first_key(objects, ["mpn", "model", "modelNumber", "sku"])
    availability = first_key(objects, ["availability"])
    if isinstance(availability, dict):
        availability = availability.get("value") or availability.get("name")

    colors = clean_values(all_key_values(objects, ["color", "colour", "colorOptions", "colourOptions"]))
    storage = clean_values(all_key_values(objects, ["storage", "storageCapacity", "storageOptions", "capacity"]))
    display = first_key(objects, ["display", "displaySize", "screenSize", "displaySpecs"])
    camera = first_key(objects, ["camera", "cameraSpecs", "cameraResolution"])

    # The page exposes Device, Storage, and Colour controls.  Use their option
    # text only as a fallback because the exact control DOM was not specified.
    for label, target in (("storage", storage), ("colour", colors), ("color", colors)):
        if not target:
            pattern = re.compile(label, re.I)
            heading = next((h for h in soup.find_all(["h2", "h3", "label", "legend"]) if pattern.search(h.get_text(" ", strip=True))), None)
            if heading:
                container = heading.parent
                target.extend(clean_values([x.get_text(" ", strip=True) for x in container.find_all(["button", "option", '[role="option"]'])]))

    return {
        "Product Title": title,
        "Model Code": model,
        "Price (INR)": price if str(currency or "INR").upper() in ("INR", "INR ", "₹") else price,
        "Color options": "; ".join(colors) if colors else None,
        "Storage capacity": "; ".join(storage) if storage else None,
        "Display specs": display,
        "Camera specs": camera,
        "Availability status": availability,
        "URL": url,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    args = parser.parse_args()

    rows = []
    try:
        workbook = load_workbook(args.input, read_only=True, data_only=True)
        sheet = workbook.active
        headers = [str(x).strip().lower() if x is not None else "" for x in next(sheet.iter_rows(values_only=True))]
        for values in sheet.iter_rows(min_row=2, values_only=True):
            row = dict(zip(headers, values))
            rows.append({key: row.get(key) for key in ("keyword", "listing_url", "detail_url")})
    except Exception as exc:
        log(f"Input read error: {exc}")
        rows = [{"keyword": None, "listing_url": TARGET_URL, "detail_url": None}]

    extracted = []
    flags = []
    seen = set()
    count = 0
    log("Starting browser-based scraper; no API was observed during inspection")

    with sync_playwright() as pw:
        browser = pw.chromium.launch(headless=True, proxy=get_proxy())
        page = browser.new_page()

        def inspect_response(response):
            try:
                body = response.body()
                signals = detect_anti_bot_signals(response.status, body.decode("utf-8", "ignore"), response.url)
                for signal in signals:
                    add_flag(flags, "anti-bot", response.url, signal)
            except Exception:
                pass

        page.on("response", inspect_response)
        for input_row in rows:
            if args.max_products is not None and count >= args.max_products:
                break
            keyword = input_row.get("keyword")
            detail_url = input_row.get("detail_url")
            listing_url = input_row.get("listing_url") or TARGET_URL
            try:
                if detail_url:
                    urls = [(str(detail_url).strip(), keyword)]
                else:
                    log(f"Opening listing: {listing_url}")
                    page.goto(str(listing_url), wait_until="domcontentloaded", timeout=60000)
                    if not dismiss_cookie_banner(page):
                        add_flag(flags, "low-confidence", listing_url, "Cookie dismissal attempted but no common consent button matched")
                    page.wait_for_timeout(1500)
                    items = product_items(jsonld_objects(page.content()))
                    if not items:
                        add_flag(flags, "low-confidence", listing_url, "ItemList JSON-LD found no usable product entries")
                    urls = []
                    for item in items:
                        if title_slug_match(item, keyword):
                            raw = item.get("url") or item.get("@id")
                            if raw:
                                urls.append((urljoin(str(listing_url), str(raw)), keyword))
                for url, item_keyword in urls:
                    if args.max_products is not None and count >= args.max_products:
                        break
                    if url in seen:
                        continue
                    seen.add(url)
                    log(f"Opening detail page: {url}")
                    page.goto(url, wait_until="domcontentloaded", timeout=60000)
                    if not dismiss_cookie_banner(page):
                        add_flag(flags, "low-confidence", url, "Cookie dismissal attempted but no common consent button matched")
                    page.wait_for_timeout(1200)
                    record = extract_detail(page, url, item_keyword)
                    if record is None:
                        continue
                    extracted.append(record)
                    count += 1
                    for field in ("Model Code", "Price (INR)", "Color options", "Storage capacity", "Display specs", "Camera specs", "Availability status"):
                        if record.get(field) in (None, ""):
                            add_flag(flags, "low-confidence", url, f"Field not exposed or not confidently extracted: {field}")
            except PlaywrightTimeoutError as exc:
                add_flag(flags, "error", str(detail_url or listing_url), f"Page timeout: {exc}")
            except Exception as exc:
                add_flag(flags, "error", str(detail_url or listing_url), f"Extraction error: {exc}")
                log(traceback.format_exc())
        browser.close()

    log(f"Writing {len(extracted)} extracted rows and {len(flags)} flags")
    out = Workbook()
    data_sheet = out.active
    data_sheet.title = "Extracted Data"
    data_headers = ["Product Title", "Model Code", "Price (INR)", "Color options", "Storage capacity", "Display specs", "Camera specs", "Availability status", "URL"]
    data_sheet.append(data_headers)
    for record in extracted:
        data_sheet.append([record.get(header) for header in data_headers])
    flag_sheet = out.create_sheet("Flags")
    flag_sheet.append(["Type", "URL", "Message"])
    for flag in flags:
        flag_sheet.append([flag["Type"], flag["URL"], flag["Message"])
    out.save(args.output)
    log("Done")


if __name__ == "__main__":
    main()
